**Solução de referência** (roda com `java RelatorioVendas.java vendas.csv`):
```java
import java.io.IOException;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.text.NumberFormat;
import java.time.LocalDate;
import java.time.YearMonth;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.format.ResolverStyle;
import java.util.*;
import java.util.stream.Collectors;

public class RelatorioVendas {

    record Venda(LocalDate data, String produto, int quantidade, BigDecimal precoUnitario) {
        BigDecimal total() {
            return precoUnitario.multiply(BigDecimal.valueOf(quantidade));
        }
    }

    record Leitura(List<Venda> vendas, List<String> erros) {}

    // STRICT + "uuuu": 31/02/2026 é rejeitado (o padrão SMART ajustaria para 28/02)
    private static final DateTimeFormatter DATA =
            DateTimeFormatter.ofPattern("dd/MM/uuuu").withResolverStyle(ResolverStyle.STRICT);

    static Venda parseLinha(String linha) {
        String[] c = linha.split(";", -1);
        if (c.length != 4) throw new IllegalArgumentException("esperava 4 colunas, veio " + c.length);
        LocalDate data;
        try {
            data = LocalDate.parse(c[0].trim(), DATA);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException("data inválida '" + c[0] + "'");
        }
        String produto = c[1].trim();
        if (produto.isEmpty()) throw new IllegalArgumentException("produto vazio");
        int quantidade;
        try {
            quantidade = Integer.parseInt(c[2].trim());
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("quantidade inválida '" + c[2] + "'");
        }
        if (quantidade <= 0) throw new IllegalArgumentException("quantidade deve ser maior que zero");
        BigDecimal preco;
        try {
            preco = new BigDecimal(c[3].trim().replace(',', '.'));
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("preço inválido '" + c[3] + "'");
        }
        if (preco.signum() <= 0) throw new IllegalArgumentException("preço deve ser maior que zero");
        return new Venda(data, produto, quantidade, preco);
    }

    static Leitura ler(List<String> linhas) {
        List<Venda> vendas = new ArrayList<>();
        List<String> erros = new ArrayList<>();
        for (int i = 1; i < linhas.size(); i++) { // i = 0 é o cabeçalho
            String linha = linhas.get(i);
            if (linha.isBlank()) continue;
            try {
                vendas.add(parseLinha(linha));
            } catch (IllegalArgumentException e) {
                erros.add("Linha " + (i + 1) + ": " + e.getMessage());
            }
        }
        return new Leitura(vendas, erros);
    }

    static Map<String, BigDecimal> faturamentoPorProduto(List<Venda> vendas) {
        return vendas.stream().collect(Collectors.groupingBy(Venda::produto,
                Collectors.reducing(BigDecimal.ZERO, Venda::total, BigDecimal::add)));
    }

    static Map<String, Integer> quantidadePorProduto(List<Venda> vendas) {
        return vendas.stream().collect(Collectors.groupingBy(Venda::produto,
                Collectors.summingInt(Venda::quantidade)));
    }

    static List<String> top3(List<Venda> vendas) {
        return faturamentoPorProduto(vendas).entrySet().stream()
                .sorted(Map.Entry.<String, BigDecimal>comparingByValue().reversed()
                        .thenComparing(Map.Entry.comparingByKey()))
                .limit(3)
                .map(Map.Entry::getKey)
                .toList();
    }

    static SortedMap<YearMonth, BigDecimal> faturamentoPorMes(List<Venda> vendas) {
        return vendas.stream().collect(Collectors.groupingBy(v -> YearMonth.from(v.data()), TreeMap::new,
                Collectors.reducing(BigDecimal.ZERO, Venda::total, BigDecimal::add)));
    }

    public static void main(String[] args) {
        if (args.length != 1) {
            System.err.println("Uso: java RelatorioVendas.java <arquivo.csv>");
            System.exit(1);
        }
        List<String> linhas;
        try {
            linhas = Files.readAllLines(Path.of(args[0]), StandardCharsets.UTF_8);
        } catch (IOException e) {
            System.err.println("Não foi possível ler o arquivo: " + e.getMessage());
            System.exit(1);
            return;
        }
        Leitura leitura = ler(linhas);
        List<Venda> vendas = leitura.vendas();
        NumberFormat reais = NumberFormat.getCurrencyInstance(Locale.of("pt", "BR"));

        System.out.printf("Linhas válidas: %d | inválidas: %d%n", vendas.size(), leitura.erros().size());
        System.out.println("\nTotal por produto:");
        Map<String, Integer> quantidades = quantidadePorProduto(vendas);
        faturamentoPorProduto(vendas).entrySet().stream()
                .sorted(Map.Entry.<String, BigDecimal>comparingByValue().reversed())
                .forEach(e -> System.out.printf("  %-8s %3d un.  %s%n",
                        e.getKey(), quantidades.get(e.getKey()), reais.format(e.getValue())));
        System.out.println("\nTop 3 por faturamento: " + String.join(", ", top3(vendas)));
        System.out.println("\nFaturamento por mês:");
        faturamentoPorMes(vendas).forEach((mes, total) -> System.out.printf("  %s  %s%n", mes, reais.format(total)));
        System.out.println("\nLinhas inválidas:");
        leitura.erros().forEach(erro -> System.out.println("  " + erro));
    }
}
```

