**Java** — implementação:
```java
import java.util.List;
import java.util.function.Predicate;
import java.util.regex.Pattern;

public class ValidadorSenha {

    public enum Erro { MINIMO_8, MAIUSCULA, MINUSCULA, DIGITO, ESPECIAL, SEM_ESPACO }

    private record Regra(Erro erro, Predicate<String> valida) {}

    private static Predicate<String> contem(String regex) {
        Pattern padrao = Pattern.compile(regex);
        return senha -> padrao.matcher(senha).find();
    }

    private static final List<Regra> REGRAS = List.of(
        new Regra(Erro.MINIMO_8, senha -> senha.length() >= 8),
        new Regra(Erro.MAIUSCULA, contem("[A-Z]")),
        new Regra(Erro.MINUSCULA, contem("[a-z]")),
        new Regra(Erro.DIGITO, contem("\\d")),
        new Regra(Erro.ESPECIAL, contem("[!@#$%^&*()\\-+]")),
        new Regra(Erro.SEM_ESPACO, contem("\\s").negate())
    );

    public List<Erro> validar(String senha) {
        if (senha == null) throw new IllegalArgumentException("senha não pode ser nula");
        return REGRAS.stream()
            .filter(regra -> !regra.valida().test(senha))
            .map(Regra::erro)
            .toList();
    }
}
