**TypeScript** (`reduce` + `Map`):
```ts
type Pedido = { cliente: string; valor: number; data: string }
type Resumo = { cliente: string; total: number; pedidos: number; media: number }

export function resumoPorCliente(pedidos: Pedido[]): Resumo[] {
  const acumulado = pedidos.reduce((mapa, { cliente, valor }) => {
    const atual = mapa.get(cliente) ?? { total: 0, pedidos: 0 }
    return mapa.set(cliente, { total: atual.total + valor, pedidos: atual.pedidos + 1 })
  }, new Map<string, { total: number; pedidos: number }>())

  return [...acumulado]
    .map(([cliente, { total, pedidos }]) => ({ cliente, total, pedidos, media: total / pedidos }))
    .sort((a, b) => b.total - a.total || a.cliente.localeCompare(b.cliente))
}

export function topClientes(pedidos: Pedido[], n = 3): Resumo[] {
  return resumoPorCliente(pedidos).slice(0, n)
}

// topClientes(pedidos) → Carla 215, Ana 170, Bruno 170
