import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;

public class RankingPedidos {

    record Pedido(String cliente, double valor, String data) {}
    record Resumo(String cliente, double total, long pedidos, double media) {}

    static List<Resumo> resumoPorCliente(List<Pedido> pedidos) {
        return pedidos.stream()
            .collect(Collectors.groupingBy(Pedido::cliente, Collectors.summarizingDouble(Pedido::valor)))
            .entrySet().stream()
            .map(e -> new Resumo(e.getKey(), e.getValue().getSum(), e.getValue().getCount(), e.getValue().getAverage()))
            .sorted(Comparator.comparingDouble(Resumo::total).reversed().thenComparing(Resumo::cliente))
            .toList();
    }

    static List<Resumo> topClientes(List<Pedido> pedidos, int n) {
        return resumoPorCliente(pedidos).stream().limit(n).toList();
    }

