@RestController
@RequestMapping("/api/clientes")
public class ClienteController {

    @Autowired
    private ClienteRepository repo;

    @Autowired
    private EntityManager em;

    @GetMapping("/busca")
    public List<Cliente> buscar(@RequestParam String nome) {
        String sql = "SELECT * FROM clientes WHERE nome LIKE '%" + nome + "%'";
        return em.createNativeQuery(sql, Cliente.class).getResultList();
    }

    @PostMapping
    public Cliente criar(@RequestBody Cliente c) {
        return repo.save(c);
    }

    @PostMapping("/{id}/transferir")
    public ResponseEntity<String> transferir(@PathVariable Long id,
                                             @RequestParam Long destino,
                                             @RequestParam double valor) {
        try {
            Cliente a = repo.findById(id).get();
            Cliente b = repo.findById(destino).get();
            if (a.getSaldo() >= valor) {
                a.setSaldo(a.getSaldo() - valor);
                repo.save(a);
                b.setSaldo(b.getSaldo() + valor);
                repo.save(b);
            }
            return ResponseEntity.ok("ok");
        } catch (Exception e) {
            return ResponseEntity.ok("erro");
        }
    }

    @DeleteMapping("/{id}")
    public String del(@PathVariable Long id) {
        repo.deleteById(id);
        return "deletado";
    }
}
