    <input v-model="novoComentario" placeholder="Escreva sua avaliação" />
    <div class="botao" @click="enviar">Enviar</div>
  </div>
</template>
```

desafios.gabarito:
**Trecho A — problemas e correções**
- **[bloqueante] SQL injection** em `buscar`: `nome = "' OR 1=1 --"` retorna todos os clientes, e com `SELECT *` vêm junto senha e saldo. Correção: `findByNomeContainingIgnoreCase(nome)` no repositório (ou `createNativeQuery("... WHERE nome LIKE :nome").setParameter("nome", "%" + nome + "%")`).
- **[bloqueante] Entidade exposta**: a resposta devolve `senha` e `saldo`; no POST, qualquer pessoa manda `"admin": true`, `"saldo": 1000000` ou um `id` existente (mass assignment). Correção: DTOs de entrada e saída.
- **[bloqueante] Senha em texto puro**: gravada como veio. Correção: `PasswordEncoder` (BCrypt) no service.
- **[bloqueante] Sem validação**: não há `@Valid` nem restrições no POST. Na transferência, `valor = -500` passa no `if` (saldo >= -500) e **aumenta** o saldo do pagador, tirando do recebedor. Também não impede transferir para si mesmo.
- **[bloqueante] Sem transação e regra no controller**: são dois `save` em transações separadas; se o segundo falhar, o dinheiro some. Correção: mover para um `@Service` com `@Transactional`, lançando exceção para desfazer tudo.
- **[importante] `double` para dinheiro**: gera erros de arredondamento. Use `BigDecimal` e coluna `NUMERIC(19,2)`.
- **[importante] Erro engolido e status errados**: `catch (Exception)` sem log devolve 200 "erro"; `Optional.get()` sem checagem vira `NoSuchElementException` (deveria ser 404); saldo insuficiente responde "ok" (deveria ser 422); POST deveria ser 201 com `Location`; DELETE deveria ser 204. Detalhe: no Spring Data 3, `deleteById` de um id inexistente não lança exceção, então o código sempre responde "deletado".
- **[importante] Parâmetros de transferência na query string** (`@RequestParam double valor`): prefira um corpo JSON validado.
- **[sugestão] Injeção por campo** (`@Autowired` em atributo): prefira construtor (facilita testes e imutabilidade). `EntityManager` no controller também mistura camadas.
- **[sugestão] Nomes**: `c`, `a`, `b`, `del`, `repo` → `cliente`, `origem`, `destino`, `excluir`, `clienteRepository`.
- **[diferencial] Concorrência**: duas transferências simultâneas leem o mesmo saldo (lost update). Use lock pessimista (`@Lock(LockModeType.PESSIMISTIC_WRITE)`) ou `@Version`. E falta autorização: qualquer pessoa pode transferir a partir de qualquer id.

**Versão corrigida (resumo, imports omitidos)** — compila com Spring Boot 3:
```java
// ---------- DTOs ----------
public record ClienteRequest(
        @NotBlank @Size(max = 100) String nome,
        @NotBlank @Email String email,
        @NotBlank @Size(min = 8) String senha) {}

public record ClienteResponse(Long id, String nome, String email) {
    static ClienteResponse de(Cliente c) {
        return new ClienteResponse(c.getId(), c.getNome(), c.getEmail());
    }
}

public record TransferenciaRequest(@NotNull Long destinoId, @NotNull @Positive BigDecimal valor) {}

// ---------- Entidade ----------
@Entity
@Table(name = "clientes")
public class Cliente {
    @Id @GeneratedValue private Long id;
    private String nome;
    private String email;
    private String senhaHash;
    @Column(precision = 19, scale = 2) private BigDecimal saldo = BigDecimal.ZERO;

    protected Cliente() {}

    public Cliente(String nome, String email, String senhaHash) {
        this.nome = nome;
        this.email = email;
        this.senhaHash = senhaHash;
    }

    public void debitar(BigDecimal valor) {
        if (saldo.compareTo(valor) < 0) throw new RegraDeNegocioException("Saldo insuficiente");
        saldo = saldo.subtract(valor);
    }

    public void creditar(BigDecimal valor) {
        saldo = saldo.add(valor);
    }

    public Long getId() { return id; }
    public String getNome() { return nome; }
    public String getEmail() { return email; }
}

// ---------- Repositório ----------
public interface ClienteRepository extends JpaRepository<Cliente, Long> {
    List<Cliente> findByNomeContainingIgnoreCase(String nome);
}

// ---------- Service ----------
@Service
public class ClienteService {
    private final ClienteRepository repositorio;
    private final PasswordEncoder passwordEncoder;

    public ClienteService(ClienteRepository repositorio, PasswordEncoder passwordEncoder) {
        this.repositorio = repositorio;
        this.passwordEncoder = passwordEncoder;
    }

    @Transactional(readOnly = true)
    public List<ClienteResponse> buscarPorNome(String nome) {
        return repositorio.findByNomeContainingIgnoreCase(nome).stream().map(ClienteResponse::de).toList();
    }

    @Transactional
    public ClienteResponse criar(ClienteRequest req) {
        var cliente = new Cliente(req.nome(), req.email(), passwordEncoder.encode(req.senha()));
        return ClienteResponse.de(repositorio.save(cliente));
    }

    @Transactional
    public void transferir(Long origemId, TransferenciaRequest req) {
        if (origemId.equals(req.destinoId())) {
            throw new RegraDeNegocioException("Origem e destino devem ser diferentes");
        }
        Cliente origem = buscar(origemId);
        Cliente destino = buscar(req.destinoId());
        origem.debitar(req.valor());
        destino.creditar(req.valor());
        // entidades gerenciadas: o JPA grava as duas alterações no commit (ou nenhuma)
    }

    @Transactional
    public void excluir(Long id) {
        repositorio.delete(buscar(id));
    }

    private Cliente buscar(Long id) {
        return repositorio.findById(id)
                .orElseThrow(() -> new RecursoNaoEncontradoException("Cliente " + id + " não encontrado"));
    }
}

// ---------- Controller ----------
@RestController
@RequestMapping("/api/clientes")
public class ClienteController {
    private final ClienteService service;

    public ClienteController(ClienteService service) {
        this.service = service;
    }

    @GetMapping("/busca")
    public List<ClienteResponse> buscar(@RequestParam String nome) {
        return service.buscarPorNome(nome);
    }

    @PostMapping
    public ResponseEntity<ClienteResponse> criar(@Valid @RequestBody ClienteRequest request) {
        ClienteResponse criado = service.criar(request);
        return ResponseEntity.created(URI.create("/api/clientes/" + criado.id())).body(criado);
    }

    @PostMapping("/{id}/transferencias")
    public ResponseEntity<Void> transferir(@PathVariable Long id,
                                           @Valid @RequestBody TransferenciaRequest request) {
        service.transferir(id, request);
        return ResponseEntity.noContent().build();
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> excluir(@PathVariable Long id) {
        service.excluir(id);
        return ResponseEntity.noContent().build();
    }
}

// ---------- Tratamento de erros ----------
@RestControllerAdvice
public class TratadorDeErros {
    @ExceptionHandler(RecursoNaoEncontradoException.class)
    public ProblemDetail naoEncontrado(RecursoNaoEncontradoException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(RegraDeNegocioException.class)
    public ProblemDetail regraDeNegocio(RegraDeNegocioException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.UNPROCESSABLE_ENTITY, e.getMessage());
    }
}
```
As exceções `RecursoNaoEncontradoException` e `RegraDeNegocioException` são `RuntimeException` simples, e o `PasswordEncoder` vem de um `@Bean` com `new BCryptPasswordEncoder()` (spring-security-crypto). Dados inválidos no `@Valid` já resultam em 400.

**Trecho B — problemas e correções**
- **[bloqueante] XSS com `v-html`**: comentários de outros usuários viram HTML. Um comentário `<img src=x onerror="...">` executa script no navegador de quem abrir a página. Correção: `{{ a.comentario }}` (o Vue escapa); se precisar de HTML, sanitize (ex.: DOMPurify).
- **[bloqueante] Mutação de prop**: `props.quantidade++` não funciona (no modo dev o Vue avisa que a prop é somente leitura e o `vue-tsc` acusa erro de tipo). Correção: `emit('update:quantidade', props.quantidade + 1)` com `v-model:quantidade` no pai, ou `defineModel` (Vue 3.4+).
- **[importante] `v-for` sem `:key`**: o Vue reaproveita elementos de forma errada ao inserir ou remover itens. Use um id estável (`:key="a.id"`), não o índice.
- **[importante] `watch` que deveria ser `computed`**: a média é um valor derivado. Além disso, `watch` em um `ref` de array sem `deep` **não dispara no `push`**, então a média não atualiza depois de `enviar()`; e com lista vazia vira `NaN` (0/0). Antes de carregar, mostra 0, o que é enganoso.
- **[importante] `fetch` sem tratamento**: sem loading, sem `try/catch` e sem checar `response.ok` (um 404 ou 500 tenta virar JSON e quebra). Também não recarrega se `produtoId` mudar.
- **[importante] Acessibilidade**: `img` sem `alt`; `input` só com placeholder (sem `label`); `div` com `@click` não recebe foco nem responde ao Enter. Use `button type="submit"` dentro de um `form`.
- **[sugestão] Tipos**: `ref<any[]>` → `interface Avaliacao`. O envio só altera a lista local, com nota fixa 5: pergunte se deveria chamar a API.

**Versão corrigida:**
```vue
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'

interface Avaliacao {
  id: number
  autor: string
  nota: number
  comentario: string
}

const props = defineProps<{ produtoId: number; quantidade: number }>()
const emit = defineEmits<{ 'update:quantidade': [valor: number] }>()

const avaliacoes = ref<Avaliacao[]>([])
const carregando = ref(false)
const erro = ref<string | null>(null)
const novoComentario = ref('')

const media = computed(() => {
  if (avaliacoes.value.length === 0) return null
  const soma = avaliacoes.value.reduce((total, a) => total + a.nota, 0)
  return soma / avaliacoes.value.length
})

async function carregar() {
  carregando.value = true
  erro.value = null
  try {
    const resposta = await fetch(`/api/produtos/${props.produtoId}/avaliacoes`)
    if (!resposta.ok) throw new Error(`HTTP ${resposta.status}`)
    avaliacoes.value = await resposta.json()
  } catch {
    erro.value = 'Não foi possível carregar as avaliações.'
  } finally {
    carregando.value = false
  }
}

onMounted(carregar)

function adicionarAoCarrinho() {
  emit('update:quantidade', props.quantidade + 1)
}

function enviarAvaliacao() {
  const comentario = novoComentario.value.trim()
  if (!comentario) return
  // idealmente: POST na API e usar o id devolvido; aqui mantemos o comportamento local do PR
  avaliacoes.value.push({ id: Date.now(), autor: 'Você', nota: 5, comentario })
  novoComentario.value = ''
}
</script>

<template>
  <section>
    <img :src="`/img/produtos/${produtoId}.jpg`" alt="Foto do produto" />
    <p v-if="media !== null">Nota média: {{ media.toFixed(1) }}</p>
    <button type="button" @click="adicionarAoCarrinho">Adicionar ao carrinho ({{ quantidade }})</button>

    <p v-if="carregando" role="status">Carregando avaliações…</p>
    <p v-else-if="erro" role="alert">
      {{ erro }} <button type="button" @click="carregar">Tentar novamente</button>
    </p>
    <p v-else-if="avaliacoes.length === 0">Nenhuma avaliação ainda.</p>
    <ul v-else>
      <li v-for="a in avaliacoes" :key="a.id">
        <strong>{{ a.autor }}</strong>
        <p>{{ a.comentario }}</p>
      </li>
    </ul>

    <form @submit.prevent="enviarAvaliacao">
      <label for="comentario">Sua avaliação</label>
      <textarea id="comentario" v-model="novoComentario" required></textarea>
      <button type="submit">Enviar</button>
    </form>
  </section>
</template>
```

